-- ===============================================================
-- Reset WELLNESS history to a clean, English "Week · Day N" state so the
-- dashboard's history-based "Up next" works, WITHOUT losing your real logs.
--   • deletes imported sessions (saved at 12:00), any title format;
--   • keeps your in-app workouts (saved at midnight) and gives the plain
--     "Day N" ones the current week prefix;
--   • re-imports the genuinely-trained past (through 2026-06-21) with
--     "Week · Day N" titles.
-- Run once, AFTER seed-wellness-claudia.sql. Safe to re-run.
-- ===============================================================
do $$
declare uid uuid; pid uuid; wkid uuid; wnotes text; s record;
begin
  select id into uid from users where lower(email) = lower('yaczoe@gmail.com');
  if uid is null then raise exception 'Registra yaczoe@gmail.com primero.'; end if;
  select id into pid from plans where user_id = uid and name = 'WELLNESS' limit 1;
  if pid is null then raise exception 'No existe el plan WELLNESS.'; end if;

  -- 1) drop imported sessions (they are stamped 12:00); keep real midnight logs
  delete from workouts where user_id = uid and plan_id = pid and performed_at::time = time '12:00:00';

  -- 2) give your in-app plain "Day N" workouts the current week prefix
  update workouts set title = 'Girls just wanna have fun · ' || title
   where user_id = uid and plan_id = pid and title ~ '^Day [0-9]+$';

  -- 3) re-import the genuinely-trained past with clean "Week · Day N" titles
  create temp table reg(ord int, d text, title text, ex text, grp text, weight numeric, reps int, rir text, note text) on commit drop;

  select uid, trim(r.ex), (array_agg(r.grp order by r.ord))[1] from reg r
  where not exists (select 1 from exercises e where (e.owner_id is null or e.owner_id = uid) and lower(trim(e.name)) = lower(trim(r.ex)))
  group by trim(r.ex);

  for s in select distinct title, d from reg order by d, title loop
    select string_agg(distinct nullif(note,''), ' · ') into wnotes from reg where title = s.title and d = s.d;
      values (uid, s.title, (s.d || ' 12:00')::timestamptz, pid, coalesce(wnotes,''))
      returning id into wkid;
    select wkid,
      (select e.id from exercises e where (e.owner_id is null or e.owner_id = uid) and lower(trim(e.name)) = lower(trim(r.ex)) order by e.owner_id nulls last limit 1),
      trim(r.ex), row_number() over (partition by lower(trim(r.ex)) order by r.ord),
      r.weight, r.reps, nullif(r.rir,'')
    from reg r where r.title = s.title and r.d = s.d order by r.ord;
  end loop;

  raise notice 'Historial WELLNESS reseteado a "Week · Day N" (pasado reimportado, logs reales conservados).';
end $$;
